import {Col, Row} from '@jetbrains/ring-ui-built/components/grid/grid'
import classNames from 'classnames'

import MiddleEllipsis from '../../../../common/MiddleEllipsis/MiddleEllipsis'
import rowStyles from '../../rows/TestRow/TestRow.module.css'

import styles from './TestsTableHeader.module.css'

type Props = {
  sourceBuildNumber: string | null | undefined
  compareBuildNumber: string | null | undefined
}

function TestsTableHeader({sourceBuildNumber, compareBuildNumber}: Props) {
  return (
    <Row className={classNames(rowStyles.row, styles.header)}>
      <Col className={rowStyles.nameCol}>{'Test'}</Col>
      <Col className={rowStyles.statusCol}>
        {sourceBuildNumber != null ? (
          <MiddleEllipsis>{`#${sourceBuildNumber}`}</MiddleEllipsis>
        ) : (
          '1st status'
        )}
      </Col>
      <Col className={rowStyles.statusCol}>
        {compareBuildNumber != null ? (
          <MiddleEllipsis>{`#${compareBuildNumber}`}</MiddleEllipsis>
        ) : (
          '2nd status'
        )}
      </Col>
      <Col className={rowStyles.durationCol}>{'Duration'}</Col>
      <Col className={rowStyles.durationDiffCol} />
    </Row>
  )
}

export default TestsTableHeader
