import compose from 'lodash/flowRight'
import {Suspense} from 'react'
import {connect} from 'react-redux'
import {graphql, useLazyLoadQuery} from 'react-relay'

import {useAppSelector} from '../../../hooks/react-redux'
import type {State} from '../../../reducers/types'
import {getBuildHref} from '../../../routes'
import {
  getBuildTriggered,
  getFullPath,
  getIsSakuraUI,
  getPipelineJobIdFromBuildId,
} from '../../../selectors'
import {resolveWebEntityLink, WebEntityType} from '../../../utils/entityLinks'
import type {VisibleProps} from '../Visible/Visible.hocs'
import {withVisibility} from '../Visible/Visible.hocs'

import type {BuildTriggeredByBuildQuery} from './__generated__/BuildTriggeredByBuildQuery.graphql'
import BuildTriggeredBy from './BuildTriggeredBy'
import type {OwnProps, StateProps} from './BuildTriggeredBy.types'

const mapStateToProps = (state: State, props: OwnProps): StateProps => {
  const triggered = getBuildTriggered(state, props.buildId)
  const jobId = getPipelineJobIdFromBuildId(state, props.buildId)

  if (!triggered) {
    return {
      text: null,
      buildType: null,
      buildPath: null,
    }
  }

  const {displayText, buildType, date} = triggered
  return {
    //TODO fix when https://youtrack.jetbrains.com/issue/TCP-1460 is ready
    text: jobId ? '<Pipeline Trigger>' : displayText,
    buildType,
    buildPath: buildType
      ? getFullPath(state, {
          nodeType: 'bt',
          id: buildType,
        })
      : null,
    date,
  }
}

const triggeredByBuildQuery = graphql`
  query BuildTriggeredByBuildQuery($buildLocator: String!, $skip: Boolean!) {
    build(buildLocator: $buildLocator) @skip(if: $skip) {
      triggered {
        build {
          id
          number
          links {
            link {
              type
              relativeUrl
            }
          }
        }
      }
    }
  }
`

function BuildTriggeredByInnerContainer(props: OwnProps & StateProps & VisibleProps) {
  const {isVisible, buildId, buildType} = props
  const isSakuraUI = useAppSelector(getIsSakuraUI)
  const {build} = useLazyLoadQuery<BuildTriggeredByBuildQuery>(
    triggeredByBuildQuery,
    {
      buildLocator: `id:${buildId}`,
      skip: buildId == null || buildType == null,
    },
    {fetchPolicy: isVisible || process.env.NODE_ENV === 'test' ? 'store-or-network' : 'store-only'},
  )
  const triggerBuild = build?.triggered?.build

  return (
    <BuildTriggeredBy
      {...props}
      buildNumber={triggerBuild?.number}
      buildUrl={
        isSakuraUI && triggerBuild?.id != null
          ? getBuildHref(triggerBuild.id, buildType)
          : resolveWebEntityLink(WebEntityType.BUILD, triggerBuild?.id)
      }
    />
  )
}

export default compose(
  connect(mapStateToProps),
  withVisibility(),
)(function BuildTriggeredByContainer(props: OwnProps & StateProps & VisibleProps) {
  return (
    <Suspense fallback={<BuildTriggeredBy {...props} />}>
      <BuildTriggeredByInnerContainer {...props} />
    </Suspense>
  )
})
