import {mapProps} from 'recompose'

import {skipToken} from '@reduxjs/toolkit/query'
import compose from 'lodash/flowRight'
import {useParams} from 'react-router'

import withHook from '../../../hocs/withHook'
import {useAppSelector} from '../../../hooks/react-redux'
import {withQueryParam} from '../../../hooks/routes'
import {getSingleBuildArg} from '../../../rest/builds'
import {getBuildLocator} from '../../../rest/locators'
import {getExtensionEndpoint} from '../../../selectors'
import {restApi} from '../../../services/rest'
import type {BuildId} from '../../../types'
import {toBuildId} from '../../../types'

import CompareBuildsPage from './CompareBuildsPage'

type OwnProps = {
  sourceId: BuildId
  compareWithId: BuildId | null | undefined
}

function useErrors({sourceId, compareWithId}: OwnProps) {
  const extensionEnabled = useAppSelector(state =>
    Boolean(getExtensionEndpoint(state, 'builds-diff')),
  )
  const {sourceBuildError} = restApi.endpoints.getBuildNormalized.useQuery(
    getSingleBuildArg(getBuildLocator(sourceId)),
    {
      selectFromResult: ({error}) => ({
        sourceBuildError: error,
      }),
    },
  )
  const {compareBuildError} = restApi.endpoints.getBuildNormalized.useQuery(
    compareWithId != null ? getSingleBuildArg(getBuildLocator(compareWithId)) : skipToken,
    {
      selectFromResult: ({error}) => ({
        compareBuildError: error,
      }),
    },
  )

  if (!extensionEnabled) {
    throw new Error('Plugin teamcity-compare-builds is not enabled')
  }
  if (sourceBuildError != null) {
    throw sourceBuildError
  }
  if (compareBuildError != null) {
    throw compareBuildError
  }
}

export default compose(
  withHook(useParams),
  withQueryParam('withBuildId'),
  mapProps(({buildIdSource, withBuildId}) => ({
    sourceId: toBuildId(buildIdSource),
    compareWithId: withBuildId != null ? toBuildId(withBuildId) : null,
  })),
  withHook(useErrors),
)(CompareBuildsPage)
